import{_ as r,c as a,o as t,ag as i}from"./chunks/framework.C86mscM5.js";const _=JSON.parse('{"title":"SSR (Server Side Rendering)","description":"","frontmatter":{},"headers":[],"relativePath":"advance/ssr/index.md","filePath":"advance/ssr/index.md","lastUpdated":1788092044000}'),n={name:"advance/ssr/index.md"};function s(d,e,o,S,l,c){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="ssr-server-side-rendering" tabindex="-1">SSR (Server Side Rendering) <a class="header-anchor" href="#ssr-server-side-rendering" aria-label="Permalink to &quot;SSR (Server Side Rendering)&quot;">​</a></h1><blockquote><p>SSR 是 &quot;Server-Side Rendering&quot;（服务器端渲染）的缩写。它表示由服务器生成网页的 HTML，并将其发送给客户端，而不是只发送一个空的 HTML 外壳，并依赖 JavaScript 来生成页面内容。</p><p>在传统的客户端渲染中，服务器会向客户端发送一个空的 HTML 外壳和一些 JavaScript 脚本，然后从服务器的 API 中获取数据，并用动态内容填充页面。这会导致页面的初始加载时间较慢，不利于用户体验和 SEO。</p><p>使用 SSR 后，服务器会生成已经包含动态内容的 HTML，并将其发送给客户端。这使得首屏加载速度更快，并对 SEO 更加友好，因为搜索引擎可以爬取到渲染后的页面。</p></blockquote><h2 id="ssr-加载流程" tabindex="-1">SSR 加载流程 <a class="header-anchor" href="#ssr-加载流程" aria-label="Permalink to &quot;SSR 加载流程&quot;">​</a></h2><ol><li>浏览器加载 HTML → 用户立即看到完整内容</li><li>JavaScript 加载完成 → React hydrate（水合），绑定事件交互</li><li>后续页面导航 → SPA 模式，客户端渲染</li></ol>',4)]))}const v=r(n,[["render",s]]);export{_ as __pageData,v as default};
